\begin{definition}[{\cite[Definition 3.1]{Calloway14}}]\label{Calloway14-def-3.1}
\label{Calloway14-def:involution}
An \emph{involution} of a space $X$ is a map $\sigma \colon X \to X$ with $\sigma \circ \sigma = \mathrm{id}_X$. Its \emph{fixed locus} is $\operatorname{Fix}(\sigma) = \{x \in X : \sigma(x) = x\}$.
\end{definition}

