\begin{proposition}[{\cite[Proposition 3.2]{Calloway14}}]\label{Calloway14-prop-3.2}
\label{Calloway14-prop:closed}
Let $X$ be a Hausdorff space and $\sigma$ an involution of $X$ in the sense of Definition~\ref{Calloway14-def-3.1}. Then $\operatorname{Fix}(\sigma)$ is closed in $X$.
\end{proposition}

