\begin{proposition}[{\cite[Proposition 3.3]{Calloway14}}]\label{Calloway14-prop-3.3}
\label{Calloway14-prop:parity}
Let $X$ be a finite set and $\sigma$ an involution of $X$. Then $|X| \equiv |\operatorname{Fix}(\sigma)| \pmod 2$.
\end{proposition}

