\begin{theorem}[{\cite[Theorem 3.4]{Calloway14}}]\label{Calloway14-thm-3.4}
\label{Calloway14-thm:both}
Let $X$ be a finite Hausdorff space and $\sigma$ an involution of $X$. Then $\operatorname{Fix}(\sigma)$ is closed and $|X| \equiv |\operatorname{Fix}(\sigma)| \pmod 2$.
\end{theorem}

